local imageStatus = {apple = "pending", mm2 = "pending"}
local customAsset = getcustomasset or getsynasset
local function decode64(data)
    local alphabet, lookup = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", {}
    for i = 1, #alphabet do lookup[alphabet:byte(i)] = i - 1 end
    local out, buffer, bits = {}, 0, 0
    for i = 1, #data do
        local n = lookup[data:byte(i)]
        if n then
            buffer, bits = buffer * 64 + n, bits + 6
            if bits >= 8 then
                bits = bits - 8
                local power = 2 ^ bits
                out[#out + 1] = string.char(math.floor(buffer / power))
                buffer = buffer % power
            end
        end
    end
    return table.concat(out)
end
local function imageAsset(override, cache, payload, key)
    if override ~= "" then imageStatus[key] = "asset ID supplied"; return override end
    if type(writefile) ~= "function" or type(customAsset) ~= "function" then
        imageStatus[key] = "local image API unavailable"; return ""
    end
    local ok, result = pcall(function()
        writefile(cache, decode64(payload))
        return customAsset(cache)
    end)
    imageStatus[key] = ok and "registered; loading" or "image registration failed"
    return ok and result or ""
end
