-- Only values actually modified by this panel are snapshotted and restored.
local modified = setmetatable({}, {__mode = "k"})
local function setOwned(obj, property, value, owner)
    if not obj then return end
    local props = modified[obj]
    if not props then props = {}; modified[obj] = props end
    if not props[property] then props[property] = {value = obj[property], owner = owner} end
    if obj[property] ~= value then obj[property] = value end
end
local function restore(owner)
    for obj, props in pairs(modified) do
        for prop, old in pairs(props) do
            if not owner or old.owner == owner then
                pcall(function()
                    local value = old.value
                    if prop == "CameraSubject" and (not value or not value.Parent) then
                        value = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                    end
                    obj[prop] = value
                end); props[prop] = nil
            end
        end
        if next(props) == nil then modified[obj] = nil end
    end
end
local function characterParts(player)
    local char = player.Character
    return char, char and char:FindFirstChildOfClass("Humanoid"), char and char:FindFirstChild("HumanoidRootPart")
end
local target, targetIndex = nil, 0
local cross = new("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5,0.5), Position = UDim2.fromScale(0.5,0.5), Size = UDim2.fromOffset(24,24), Visible = false}, gui)
