new("Frame", {Size = UDim2.fromOffset(2,22), Position = UDim2.fromOffset(11,1), BorderSizePixel = 0, BackgroundColor3 = C.red}, cross)
local espObjects, nameObjects, gunObjects, gunCandidates = {}, {}, {}, {}
local function erase(objects)
    for key, o in pairs(objects) do o:Destroy(); objects[key] = nil end
end
local function observedRole(player)
    for _, root in pairs({character = player.Character, backpack = player:FindFirstChildOfClass("Backpack")}) do
        for _, obj in ipairs(root:GetChildren()) do
            if obj:IsA("Tool") and string.lower(obj.Name) == "knife" then return "knife", C.red end
        end
    end
    for _, root in pairs({character = player.Character, backpack = player:FindFirstChildOfClass("Backpack")}) do
        for _, obj in ipairs(root:GetChildren()) do
            if obj:IsA("Tool") and string.lower(obj.Name) == "gun" then return "gun", C.blue end
        end
    end
    return "unknown", C.muted
end
local function roleText(role)
    if role == "knife" then return tr("พบมีด", "Knife seen") end
    if role == "gun" then return tr("พบปืน", "Gun seen") end
    return tr("ไม่ทราบบทบาท", "Role unknown")
end
local function makeBillboard(adornee, color)
    local b = new("BillboardGui", {AlwaysOnTop = true, Size = UDim2.fromOffset(240,48),
        StudsOffset = Vector3.new(0,3.1,0), MaxDistance = 2500, Adornee = adornee}, world)
    local label = text(b, "", UDim2.fromScale(1,1), UDim2.new(), color, 14)
    label.Name = "Caption"; label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextStrokeTransparency = 0.25; label.TextStrokeColor3 = Color3.new(0,0,0)
    return b
end
local function rememberGun(obj)
    local name = string.lower(obj.Name)
    if (name == "gundrop" or name == "droppedgun") and (obj:IsA("BasePart") or obj:IsA("Model")) then
        gunCandidates[obj] = true
    end
end
local function startGunScan()
    gunCandidates = {}
    for _, o in ipairs(workspace:GetDescendants()) do rememberGun(o) end
end
connect(workspace.DescendantAdded, function(o) if state.gun then rememberGun(o) end end)
connect(workspace.DescendantRemoving, function(o)
    gunCandidates[o] = nil
    if gunObjects[o] then gunObjects[o]:Destroy(); gunObjects[o] = nil end
end)
local function updateVisuals()
    local _, _, myRoot = characterParts(LP)
    local valid = {}
    if state.esp or state.names then
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP then
                local char, hum, root = characterParts(player)
                if char and hum and hum.Health > 0 and root then
                    valid[player] = true
                    local role, color = observedRole(player)
                    if state.esp then
                        if not espObjects[player] then
                            espObjects[player] = new("Highlight", {DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
                                FillTransparency = 0.78, OutlineTransparency = 0.1}, world)
                        end
                        local h = espObjects[player]; h.Adornee = char; h.FillColor = color; h.OutlineColor = color
                    end
                    if state.names then
                        if not nameObjects[player] then nameObjects[player] = makeBillboard(root, color) end
                        local b = nameObjects[player]; b.Adornee = root
                        local dist = myRoot and string.format(" · %dm", math.floor((myRoot.Position-root.Position).Magnitude * 0.28)) or ""
                        b.Caption.Text = player.DisplayName .. "\n" .. roleText(role) .. dist
                        b.Caption.TextColor3 = color; b.Caption.FontFace = fonts[state.lang]
                    end
                end
            end
        end
    end
    for player, o in pairs(espObjects) do if not state.esp or not valid[player] then o:Destroy(); espObjects[player] = nil end end
    for player, o in pairs(nameObjects) do if not state.names or not valid[player] then o:Destroy(); nameObjects[player] = nil end end
    if state.gun then
        for obj in pairs(gunCandidates) do
            if obj:IsDescendantOf(workspace) then
                local part = obj:IsA("BasePart") and obj or obj:FindFirstChildWhichIsA("BasePart", true)
                if part then
                    if not gunObjects[obj] then gunObjects[obj] = makeBillboard(part, C.gold) end
                    gunObjects[obj].Adornee = part
                    gunObjects[obj].Caption.Text = tr("ปืนตก", "Dropped gun")
                    gunObjects[obj].Caption.FontFace = fonts[state.lang]
                end
            else gunCandidates[obj] = nil end
        end
    end
end
local function spectateNext()
    local eligible = {}
    for _, p in ipairs(Players:GetPlayers()) do
        local _, h = characterParts(p)
        if p ~= LP and h and h.Health > 0 then table.insert(eligible, p) end
    end
    table.sort(eligible, function(a,b) return a.UserId < b.UserId end)
    if #eligible == 0 then
        state.spectate = false; target = nil; restore("spectate")
        toast(tr("ยังไม่มีผู้เล่นให้ติดตาม", "No player available to spectate")); return
    end
    targetIndex = targetIndex % #eligible + 1; target = eligible[targetIndex]; state.spectate = true
    local _, hum = characterParts(target)
    local cam = workspace.CurrentCamera
    if cam then
        setOwned(cam, "CameraType", Enum.CameraType.Custom, "spectate")
        setOwned(cam, "CameraSubject", hum, "spectate")
    end
    toast(tr("กำลังดู: ", "Watching: ") .. target.DisplayName)
end
apply = function(key)
    if key == "crosshair" then cross.Visible = state.crosshair end
    if key == "gun" then
        if state.gun then startGunScan() else erase(gunObjects); gunCandidates = {} end
    end
    if key == "esp" and not state.esp then erase(espObjects) end
    if key == "names" and not state.names then erase(nameObjects) end
    if key == "spectate" then
        if state.spectate then spectateNext() else target = nil; restore("spectate") end
    end
    if state[key] == false then restore(key) end
end
local function enforce()
    local char, hum = characterParts(LP)
    if hum and hum.Health > 0 then
        if state.speed then setOwned(hum, "WalkSpeed", state.speedValue, "speed") end
        if state.jump then
            -- Supports both Roblox jumping modes without changing the game's mode.
            if hum.UseJumpPower then
                setOwned(hum, "JumpPower", math.sqrt(2 * math.max(workspace.Gravity,1) * state.jumpValue), "jump")
            else setOwned(hum, "JumpHeight", state.jumpValue, "jump") end
        end
    end
    local cam = workspace.CurrentCamera
    if state.fov and cam then setOwned(cam, "FieldOfView", state.fovValue, "fov") end
    if state.zoom then setOwned(LP, "CameraMaxZoomDistance", math.max(state.zoomValue,LP.CameraMinZoomDistance), "zoom") end
    if state.bright then
        setOwned(Lighting, "Brightness", 2, "bright")
        setOwned(Lighting, "Ambient", Color3.fromRGB(180,180,180), "bright")
        setOwned(Lighting, "OutdoorAmbient", Color3.fromRGB(180,180,180), "bright")
        setOwned(Lighting, "ClockTime", 14, "bright")
    end
    if state.spectate and target then
        local _, h = characterParts(target)
        if target.Parent == Players and h and h.Health > 0 and cam then
            setOwned(cam, "CameraSubject", h, "spectate")
        else state.spectate = false; target = nil; restore("spectate"); refresh() end
    end
end
connect(RunService.PreSimulation, function()
    if not state.noclip or dead then return end
    local char, hum = characterParts(LP)
    if char and hum and hum.Health > 0 then
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then setOwned(part, "CanCollide", false, "noclip") end
        end
    end
end)
local jumped = 0
connect(UserInputService.JumpRequest, function()
    if state.airJump and os.clock() - jumped > 0.18 and not UserInputService:GetFocusedTextBox() then
        local _, hum = characterParts(LP)
        if hum and hum.Health > 0 then
            jumped = os.clock(); hum:ChangeState(Enum.HumanoidStateType.Jumping)
        end
    end
end)
local accum, lastError = 0, -10
connect(RunService.Heartbeat, function(dt)
    if dead then return end
    local ok, err = pcall(enforce)
    accum = accum + dt
    if accum >= 0.25 then accum = 0; if ok then ok, err = pcall(updateVisuals) end end
    if not ok and os.clock() - lastError > 5 then
        lastError = os.clock(); warn("[apple_hup] " .. tostring(err))
        toast(tr("บางฟีเจอร์ทำงานไม่ได้ ดู Console", "A feature failed; see console"))
    end
end)
connect(Players.PlayerRemoving, function(p)
    if espObjects[p] then espObjects[p]:Destroy(); espObjects[p] = nil end
    if nameObjects[p] then nameObjects[p]:Destroy(); nameObjects[p] = nil end
end)
connect(LP.CharacterAdded, function()
    task.defer(function()
        if dead then return end
        restore("speed"); restore("jump"); restore("noclip")
        if state.spectate then state.spectate = false; target = nil; restore("spectate"); refresh() end
    end)
end)

local function saveProfile()
    if type(writefile) ~= "function" then toast(tr("เครื่องนี้ไม่รองรับการบันทึกไฟล์", "File saving is unavailable")); return end
    writefile(CONFIG.PROFILE, HttpService:JSONEncode({version = 1, lang = state.lang, uiScale = state.uiScale,
        fovValue = state.fovValue, zoomValue = state.zoomValue, crosshair = state.crosshair}))
    toast(tr("บันทึกการแสดงผลแล้ว", "Display profile saved"))
end
local function loadProfile()
    if type(readfile) ~= "function" then toast(tr("เครื่องนี้ไม่รองรับการอ่านไฟล์", "File reading is unavailable")); return end
    local ok, data = pcall(function() return HttpService:JSONDecode(readfile(CONFIG.PROFILE)) end)
    if not ok or type(data) ~= "table" or data.version ~= 1 then toast(tr("ยังไม่มีโปรไฟล์ V1 ที่อ่านได้", "No valid V1 profile found")); return end
    if data.lang == "th" or data.lang == "en" then state.lang = data.lang end
    local function number(key, min, max)
        local value = data[key]
        if type(value) == "number" and value == value and value > -math.huge and value < math.huge then state[key] = math.clamp(value,min,max) end
    end
    number("uiScale",0.75,1.2); number("fovValue",50,110); number("zoomValue",12,120)
    if type(data.crosshair) == "boolean" then state.crosshair = data.crosshair end
    apply("crosshair"); resize(); refresh(); toast(tr("โหลดการแสดงผลแล้ว", "Display profile loaded"))
end
resetAll = function()
    for _, key in ipairs({"speed","jump","airJump","noclip","esp","names","gun","bright","fov","crosshair","spectate","zoom"}) do state[key] = false end
    target = nil; restore(); erase(espObjects); erase(nameObjects); erase(gunObjects); gunCandidates = {}
    cross.Visible = false; state.speedValue = 24; state.jumpValue = 12; state.fovValue = 80; state.zoomValue = 60; state.uiScale = 1
    if resize then resize() end
    if refresh then refresh() end
end
unload = function()
    if dead then return end
    dead = true; disconnect(connections); disconnect(pageConnections)
    if modalConnection then modalConnection:Disconnect() end
    restore(); world:Destroy(); gui:Destroy()
    if env.__APPLE_HUP_V1 and env.__APPLE_HUP_V1.Gui == gui then env.__APPLE_HUP_V1 = nil end
end
env.__APPLE_HUP_V1 = {Unload = unload, Gui = gui}
connect(unloadEvent.Event, unload)
connect(gui.Destroying, unload)

-- Responsive cards: each feature has a persistent number, readable description,
-- and controls below its text (avoids overlap on portrait phone screens).
local function card(id, th, en, dth, den, height)
    local f = new("Frame", {Name = "Feature" .. id, Size = UDim2.new(1,0,0,height or 138), BackgroundColor3 = C.card, BorderSizePixel = 0, LayoutOrder = id}, scroll)
    corner(f,12); stroke(f)
    text(f,string.format("%02d",id),UDim2.fromOffset(28,27),UDim2.fromOffset(12,10),C.red,13)
    text(f,tr(th,en),UDim2.new(1,-56,0,30),UDim2.fromOffset(44,8),C.text,17)
    text(f,tr(dth,den),UDim2.new(1,-26,0,46),UDim2.fromOffset(13,40),C.muted,13)
    return f
end
local function toggleControl(f, key, width)
    local b
    b = button(f, state[key] and tr("เปิด","ON") or tr("ปิด","OFF"), UDim2.fromOffset(width or 85,34), UDim2.fromOffset(13,92), function()
        state[key] = not state[key]; apply(key); refresh()
    end)
    b.BackgroundColor3 = state[key] and C.red or C.soft
end
local function toggle(id, th,en,dth,den,key)
    local f = card(id,th,en,dth,den); toggleControl(f,key); return f
end
local function valueControls(f,key,min,max,step,unit,x)
    x = x or 109
    local value = text(f, tostring(state[key]) .. (unit or ""), UDim2.fromOffset(62,34), UDim2.fromOffset(x+39,92), C.text,15)
    value.TextXAlignment = Enum.TextXAlignment.Center
    local function adjust(n)
        state[key] = math.floor(math.clamp(state[key] + n,min,max) * 100 + 0.5)/100
        value.Text = tostring(state[key]) .. (unit or "")
        if key == "uiScale" then resize() end
    end
    button(f,"−",UDim2.fromOffset(34,34),UDim2.fromOffset(x,92),function() adjust(-step) end)
    button(f,"+",UDim2.fromOffset(34,34),UDim2.fromOffset(x+106,92),function() adjust(step) end)
end
local function action(f,th,en,fn)
    return button(f,tr(th,en),UDim2.new(1,-26,0,34),UDim2.fromOffset(13,92),fn)
end
