local dragging, dragInput, dragStart, windowStart, moved = false, nil, nil, nil, false
local function clampPosition(pos)
    local v = gui.AbsoluteSize; local size = main.AbsoluteSize
    local halfX, halfY = size.X / 2, size.Y / 2
    return UDim2.fromOffset(math.clamp(pos.X,halfX+5,math.max(halfX+5,v.X-halfX-5)), math.clamp(pos.Y,halfY+5,math.max(halfY+5,v.Y-halfY-5)))
end
resize = function()
    if dead then return end
    local v = gui.AbsoluteSize
    if v.X < 1 or v.Y < 1 then return end
    local portrait = v.X < 600 or v.X < v.Y
    local w, h, side = portrait and 460 or 820, portrait and 660 or 590, portrait and 130 or 160
    main.Size = UDim2.fromOffset(w,h)
    scale.Scale = math.min(state.uiScale,(v.X-16)/w,(v.Y-34)/h)
    sidebar.Size = UDim2.new(0,side,1,-55)
    body.Position = UDim2.fromOffset(side+14,70); body.Size = UDim2.new(1,-side-28,1,-86)
    main.Position = UDim2.fromScale(0.5,0.5)
end
connect(gui:GetPropertyChangedSignal("AbsoluteSize"),resize)
connect(top.InputBegan,function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging=true; dragInput=input; dragStart=input.Position
        windowStart=main.AbsolutePosition + main.AbsoluteSize/2
    end
end)
connect(UserInputService.InputChanged,function(input)
    if dragging and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseMovement) then
        local delta=input.Position-dragStart
        main.Position=clampPosition(windowStart+Vector2.new(delta.X,delta.Y))
    end
end)
connect(UserInputService.InputEnded,function(input)
    if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then dragging=false; dragInput=nil end
end)
connect(UserInputService.InputBegan,function(input,processed)
    if not processed and not UserInputService:GetFocusedTextBox() and input.KeyCode == Enum.KeyCode.RightShift then main.Visible=not main.Visible end
end)
refresh(); resize()
