    if dead then return end
    local ok = pcall(function() ContentProvider:PreloadAsync({apple,mm2}) end)
    if dead then return end
    imageStatus.apple = apple.Image ~= "" and (apple.IsLoaded and "loaded" or "not loaded") or imageStatus.apple
    imageStatus.mm2 = mm2.Image ~= "" and (mm2.IsLoaded and "loaded" or "not loaded") or imageStatus.mm2
    if not ok then warn("[apple_hup] Some image assets did not preload") end
end)
